    @Query('getMethod[HttpVerbs=GET]';;'JExpression';;'order';;skip;;take;;noTracking;;Body) // expose dataResults
/*Chama o método "GetTesteSimpleViewByEntitySearch", passando o JExpression "TesteSimpleView{IDTesteSimple#<=#I100}" (pesquisa a propriedade TesteSimpleView.IDTesteSimple menor que 100), ordenando pela coluna 'DataObrigatoria', Skip de 10 (Ignorando os 10 primeiros resultados), e Take (buscando) 100 registros, noTracking foi colocado como falso (não será rastreado pelo breeze), o Body ou callback será chamado após o retorno dos dados, nesse caso está sendo exibido um alert com o total de objetos retornados.*/
@Query('GetTesteSimpleViewByEntitySearch';;'TesteSimpleView{IDTesteSimple#<=#I100}';;'DataObrigatoria';;10;;100;;false;;@ShowAlert(dataResults.length.toString()))
@Query('GetTesteSimpleView';;null;;null;;0;;0;;false;;@ShowAlert(dataResults.length.toString()))

