    //Importa a Lista de SKUs
    tipoArquivo:        1 - Definição de Inventário
                          2 - Coleta de Inventário
                          3 - Remarcação de Preços    
    salvaDadosServidor: true          (efetuar o insert nas tabelas ou só retornar a lista dos dados lidos)
                          false
    salvaLog:           true          (se gera um arquivo de log para o usuário baixar)
                          false
    nomeArquivoLog:     arquivo.txt   (nome do arquivo do log)
    callback:           'erro'        (se ocorreu um erro na chamada da API)
                          true          (se a importacao ocorreu com sucesso)
                          false         (se a importação não ocorreu com sucesso)

    @ImportaArquivoSKUs(formData;;3;;true;;true;;'LogRemarcacaoPrecos.txt', function(retorno, data)
			{
				if (retorno == true) {
					if (vm._ImportarAposSalvar == false){
						@Foreach(data.Lista;;

							var sku = BuscarSKUListaSKU(element.IdSku);

							if (sku == null)
							var sku = @CreateDetailNoCurrent(ListaSKU;;@TbCurrentData());

							@SetValue(sku;;IdSku;;element.IdSku);
							@SetValue(sku;;CodSku;;element.CodSku);
							@SetValue(sku;;DescSku;;element.DescSku);
							@SetValue(sku;;Preco;;element.Preco);	
						)

						@NotifyDetail(ListaSKU);
					}
					else {
						vm._ImportarAposSalvar = false;
						vm._ImportarFormData = null;
						@RefreshCurrentParent();
					}
				} else if (retorno == 'erro') {
					vm._ImportarAposSalvar = false;
					vm._ImportarFormData = null;
				}

			});
